function norm(v){return String(v||"").toLowerCase().replace(/ä/g,"ae").replace(/ö/g,"oe").replace(/ü/g,"ue").replace(/ß/g,"ss").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/(?:strasse|str\.?)\b/g,"str").replace(/[^a-z0-9]/g,"");}
function fail(m){var e=new Error(m);e.name="Bewertungsfehler";throw e;}
function num(v){var n=Number(v);return Number.isFinite(n)?n:NaN;}
